pub export fn SDL_BlendLine(dst: [*c]SDL_Surface, arg_x1: c_int, arg_y1_1: c_int, arg_x2: c_int, arg_y2: c_int, blendMode: SDL_BlendMode, r: Uint8, g: Uint8, b: Uint8, a: Uint8) bool {
    @setEvalBranchQuota(100000);
    var x1 = arg_x1;
    _ = &x1;
    var y1_1 = arg_y1_1;
    _ = &y1_1;
    var x2 = arg_x2;
    _ = &x2;
    var y2 = arg_y2;
    _ = &y2;
    var func: BlendLineFunc = undefined;
    _ = &func;
    if (!SDL_SurfaceValid(dst)) {
        return SDL_SetError_REAL("Parameter '%s' is invalid", @as([*c]u8, @as([*c]u8, @constCast("SDL_BlendLine(): dst"))));
    }
    func = SDL_CalculateBlendLineFunc(dst.*.fmt);
    if (!(func != null)) {
        return SDL_SetError_REAL("SDL_BlendLine(): Unsupported surface format");
    }
    if (!SDL_GetRectAndLineIntersection_REAL(&dst.*.clip_rect, &x1, &y1_1, &x2, &y2)) {
        return @"true" != 0;
    }
    func.?(dst, x1, y1_1, x2, y2, blendMode, r, g, b, a, @"true" != 0);
    return @"true" != 0;
}
pub export fn SDL_BlendLines(dst: [*c]SDL_Surface, points: [*c]const SDL_Point, count: c_int, blendMode: SDL_BlendMode, r: Uint8, g: Uint8, b: Uint8, a: Uint8) bool {
    @setEvalBranchQuota(100000);
    var i: c_int = undefined;
    _ = &i;
    var x1: c_int = undefined;
    _ = &x1;
    var y1_1: c_int = undefined;
    _ = &y1_1;
    var x2: c_int = undefined;
    _ = &x2;
    var y2: c_int = undefined;
    _ = &y2;
    var draw_end: bool = undefined;
    _ = &draw_end;
    var func: BlendLineFunc = undefined;
    _ = &func;
    if (!SDL_SurfaceValid(dst)) {
        return SDL_SetError_REAL("SDL_BlendLines(): Passed NULL destination surface");
    }
    func = SDL_CalculateBlendLineFunc(dst.*.fmt);
    if (!(func != null)) {
        return SDL_SetError_REAL("SDL_BlendLines(): Unsupported surface format");
    }
    {
        i = 1;
        while (i < count) : (i += 1) {
            x1 = points[@bitCast(@as(isize, @intCast(i - @as(c_int, 1))))].x;
            y1_1 = points[@bitCast(@as(isize, @intCast(i - @as(c_int, 1))))].y;
            x2 = points[@bitCast(@as(isize, @intCast(i)))].x;
            y2 = points[@bitCast(@as(isize, @intCast(i)))].y;
            if (!SDL_GetRectAndLineIntersection_REAL(&dst.*.clip_rect, &x1, &y1_1, &x2, &y2)) {
                continue;
            }
            draw_end = (x2 != points[@bitCast(@as(isize, @intCast(i)))].x) or (y2 != points[@bitCast(@as(isize, @intCast(i)))].y);
            func.?(dst, x1, y1_1, x2, y2, blendMode, r, g, b, a, draw_end);
        }
    }
    if ((points[@as(c_int, 0)].x != points[@bitCast(@as(isize, @intCast(count - @as(c_int, 1))))].x) or (points[@as(c_int, 0)].y != points[@bitCast(@as(isize, @intCast(count - @as(c_int, 1))))].y)) {
        _ = SDL_BlendPoint(dst, points[@bitCast(@as(isize, @intCast(count - @as(c_int, 1))))].x, points[@bitCast(@as(isize, @intCast(count - @as(c_int, 1))))].y, blendMode, r, g, b, a);
    }
    return @"true" != 0;
}

